import{_ as t,o,c as a,a2 as s}from"./chunks/framework.Cz0TtJv6.js";const p=JSON.parse('{"title":"Risk & sizing","description":"How DLMM Bot sizes positions (Kelly) and what stops it from digging holes — circuit breaker, cluster brake, regime filter, HALT/PAUSE, watchdog, and the paper-to-live promotion gate.","frontmatter":{"title":"Risk & sizing","description":"How DLMM Bot sizes positions (Kelly) and what stops it from digging holes — circuit breaker, cluster brake, regime filter, HALT/PAUSE, watchdog, and the paper-to-live promotion gate."},"headers":[],"relativePath":"risk.md","filePath":"risk.md","lastUpdated":1786714151000}'),r={name:"risk.md"};function n(i,e,l,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="risk-sizing" tabindex="-1">Risk &amp; sizing <a class="header-anchor" href="#risk-sizing" aria-label="Permalink to &quot;Risk &amp; sizing&quot;">​</a></h1><p>Memecoin LP expectancy comes from <strong>many small fee wins plus rare full losses</strong> on rugs that beat the safety triggers. The vetting engine cannot catch a well-executed slow rug — sizing caps and brakes are the real defense. This page is how the bot decides <em>how big</em>, and everything that can stop it.</p><div class="danger custom-block"><p class="custom-block-title">The honest frame</p><p>You can lose 100% of the funds under this bot&#39;s control. Nothing here removes that; it bounds it. Burner wallet only, paper first. Not financial advice.</p></div><h2 id="the-bankroll" tabindex="-1">The bankroll <a class="header-anchor" href="#the-bankroll" aria-label="Permalink to &quot;The bankroll&quot;">​</a></h2><p>The bankroll is whatever the dedicated burner wallet holds. Before anything deploys:</p><ul><li><strong>Operational reserve:</strong> 1.0 SOL + 10% of bankroll is held back for rent, priority fees, and claim transactions — never deployed.</li><li><strong>Slots:</strong> max <strong>5</strong> concurrent positions (tranches count). Small wallets simply run fewer, larger slots: at the 0.3 SOL minimum position, effective slots = <code>min(5, floor(deployable / 0.3))</code>.</li></ul><h2 id="kelly-sizing" tabindex="-1">Kelly sizing <a class="header-anchor" href="#kelly-sizing" aria-label="Permalink to &quot;Kelly sizing&quot;">​</a></h2><p>Position size is a fraction of the wallet, learned from <strong>your own rolling closed-trade ledger</strong> — not from anyone&#39;s backtest:</p><ol><li><strong>Cold start</strong> — until 50 closed positions exist, every position is a flat <strong>3% of wallet</strong>.</li><li><strong>Estimate f*</strong> — from the 50 most recent closes: <code>f* = p − (1−p)/b</code>, where <code>p</code> = win rate and <code>b</code> = average win / average loss (as return fractions). The estimator uses <strong>measured wallet-delta PnL</strong>, not notional marks.</li><li><strong>Apply a fraction of it</strong> — the bot bets <code>kelly_fraction × f*</code>. Shipped default is <strong>0.25 (quarter-Kelly)</strong>: half-Kelly is calibrated for a <em>known</em> edge, and a young book hasn&#39;t demonstrated one. Fractional Kelly keeps most of the growth with far smaller drawdowns and buffers estimation error — betting past full Kelly turns long-run growth negative.</li><li><strong>Score tilt</strong> — the scan score multiplies the result: 0.5× (score 60–70), 1.0× (70–85), 1.5× (85+).</li><li><strong>Clamps</strong> — hard cap <strong>10% of wallet</strong> per position no matter how good f* looks; floor of <strong>0.3 SOL</strong> (below it, fees can&#39;t beat tx + rent overhead; re-entries get a separate 0.2 SOL floor).</li></ol><p><strong>Negative edge:</strong> if the ledger says f* ≤ 0, the shipped behavior (<code>kelly_block_negative = false</code>) clamps sizing to the minimum floor — small size while the sample rebuilds. The alternative hard block (<code>true</code>) stops new entries entirely until the strategy re-earns its sizing; it&#39;s off by default because blocked entries produce no new closes, so f* could never recover on its own.</p><p>Follow-mode legs are <strong>excluded</strong> from this ledger and fixed at 0.25 SOL — the mode must earn bigger sizing with its own closed-leg evidence.</p><h2 id="per-token-and-pool-share-caps" tabindex="-1">Per-token and pool-share caps <a class="header-anchor" href="#per-token-and-pool-share-caps" aria-label="Permalink to &quot;Per-token and pool-share caps&quot;">​</a></h2><ul><li><strong>1</strong> primary position per token (plus an optional tranche at score ≥ 85).</li><li>Never two tokens from the same creator.</li><li>Never more than <strong>40%</strong> of deployable in one token including its tranche.</li><li>Never a position exceeding <strong>20%</strong> of pool TVL (10% for micro, 5% for majors) — beyond that, <em>we&#39;d be</em> the exit liquidity.</li><li>Micro sleeve: max 1 slot, 0.45 SOL cap, ≤5% of wallet total. Majors: max 1 slot, ≤40% of wallet, fixed 0.75 SOL entries.</li></ul><h2 id="bin-rent-budget" tabindex="-1">Bin-rent budget <a class="header-anchor" href="#bin-rent-budget" aria-label="Permalink to &quot;Bin-rent budget&quot;">​</a></h2><p>Opening a range can create new bin arrays at ~0.075 SOL each, <strong>non-refundable</strong>. The gate:</p><ul><li>Soft budget <strong>0.075 SOL</strong> (one array) — the planner shrinks the range first.</li><li>Hard budget <strong>0.15 SOL</strong> (two arrays) only when score ≥ <strong>80</strong>, and only after quoting the <em>actual</em> uninitialized arrays on-chain.</li><li>Never more than two arrays. If the RPC quote fails, the bot assumes worst case and blocks (fail closed).</li></ul><p>Position-account rent (~0.057 SOL) is refunded on close — bin-array rent is the cost that silently eats meme LPs, so it&#39;s budgeted explicitly.</p><h2 id="the-brakes" tabindex="-1">The brakes <a class="header-anchor" href="#the-brakes" aria-label="Permalink to &quot;The brakes&quot;">​</a></h2><p>Three independent systems can stop <strong>new entries</strong> (open positions are always still managed):</p><table tabindex="0"><thead><tr><th>Brake</th><th>Trips when</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Circuit breaker</strong></td><td>Realized loss &gt; <strong>3%</strong> of bankroll in a rolling 24h</td><td>No new entries for <strong>12h</strong>. Two trips in 7 days → full halt until manually resumed</td></tr><tr><td><strong>Cluster brake</strong></td><td><strong>4</strong> lossy hard exits (realized ≤ −10% of entry) within <strong>6h</strong></td><td>Pause new entries <strong>2h</strong> — catches a dump cluster before the wallet-% breaker can</td></tr><tr><td><strong>Regime filter</strong></td><td>SOL/USD −<strong>8%</strong> in 24h → halve all new sizes; −<strong>15%</strong> → pause new entries</td><td>Meme liquidity dies in SOL crashes</td></tr></tbody></table><p>The circuit breaker started at the spec&#39;s 10% and was tightened to 3% after live data: the worst observed day (−0.159 SOL on a ~24 SOL book) was still under even the 3% line, which is why the cluster brake exists as a faster, count-based trigger.</p><h2 id="halt-vs-pause-vs-off" tabindex="-1">HALT vs PAUSE vs OFF <a class="header-anchor" href="#halt-vs-pause-vs-off" aria-label="Permalink to &quot;HALT vs PAUSE vs OFF&quot;">​</a></h2><p>Three different &quot;stop&quot; concepts — don&#39;t confuse them:</p><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th><th>Positions?</th><th>How</th></tr></thead><tbody><tr><td><strong>PAUSE / engine OFF</strong></td><td>Freeze trading — no scans act, no entries, no exits initiated</td><td><strong>Stay open</strong>, still watched</td><td>Dashboard header ON/OFF toggle, or <code>npm run pause</code> (writes a <code>PAUSE</code> file; run again to clear)</td></tr><tr><td><strong>HALT</strong></td><td>Kill switch: close <strong>everything</strong>, swap to SOL, then idle</td><td><strong>All closed</strong></td><td>Dashboard red HALT button (confirm with dash token), or <code>npm run halt</code> (writes a <code>HALT</code> file; run again to clear/resume)</td></tr><tr><td><strong>Paper mode</strong></td><td>Full pipeline, simulated fills, no wallet needed</td><td>Simulated</td><td><code>FARMER_MODE=paper</code> (the default)</td></tr></tbody></table><h2 id="watchdog-liveness" tabindex="-1">Watchdog &amp; liveness <a class="header-anchor" href="#watchdog-liveness" aria-label="Permalink to &quot;Watchdog &amp; liveness&quot;">​</a></h2><ul><li><strong>No blind liquidation.</strong> If RPC goes dark for <strong>5 minutes</strong>, the bot alerts and freezes new entries — it never closes positions it cannot see. The old &quot;blind close-all&quot; was <strong>removed from the code</strong> (not just disabled): closing requires strictly more RPC than marking, so it could only ever complete when firing it was a mistake.</li><li><strong>Out-of-process heartbeat.</strong> The manager writes a heartbeat row at the end of every tick; <code>deploy/heartbeat-check.cjs</code> (run from cron, dependency-free, imports nothing from <code>src/</code>) alerts via Telegram when it goes stale. Every in-process alert dies with the process — &quot;no messages&quot; reads identically to &quot;quiet market&quot; — which is exactly why the checker lives outside.</li><li><strong>Restart safety.</strong> Positions live in SQLite. On startup the bot reconciles against the chain — <strong>on-chain state wins</strong> — repairs the DB, and resumes. Restarts are safe by design.</li></ul><h2 id="one-instance-per-wallet" tabindex="-1">One instance per wallet <a class="header-anchor" href="#one-instance-per-wallet" aria-label="Permalink to &quot;One instance per wallet&quot;">​</a></h2><p>The loop holds a lock file (<code>data/farmer.lock</code>). <strong>Never run two bot processes against the same wallet/DB</strong> — they would double-trade the same strategy, and in live mode, the same wallet. The lock is per-machine, so a dev-PC loop plus a server loop is the dangerous case; when the server takes over, stop the local one.</p><div class="warning custom-block"><p class="custom-block-title">Windows kill gotcha</p><p>On Windows, killing a background <code>npm run run</code> kills only the npm wrapper — the <code>tsx</code> child <strong>survives and keeps trading</strong>. Kill every node process whose command line matches the repo path, then delete <code>data/farmer.lock</code>.</p></div><h2 id="paper-first-the-promotion-gate" tabindex="-1">Paper first: the promotion gate <a class="header-anchor" href="#paper-first-the-promotion-gate" aria-label="Permalink to &quot;Paper first: the promotion gate&quot;">​</a></h2><ul><li><strong>Paper is the default.</strong> The full brain runs against live pool data; fills are simulated; no wallet is needed.</li><li><strong>Promotion gate:</strong> <code>npm run status</code> tracks a scoreboard of consecutive profitable paper days (realized + change in unrealized, after simulated costs). Eligibility requires <strong>7 consecutive profitable days</strong> (<code>paper_promotion_days</code>).</li><li><strong>Live is double-gated:</strong> it needs <code>[exec] mode = &quot;live&quot;</code> in config <strong>and</strong> <code>FARMER_MODE=live</code> in the environment. Either one alone keeps the bot in paper. This is deliberate: no single mis-click, bad config push, or stray env var can start spending real SOL.</li></ul><p>The gate is advisory — the bot won&#39;t stop you from flipping both switches early — but the scoreboard exists so the decision is made on evidence.</p><h2 id="the-usage-fee" tabindex="-1">The usage fee <a class="header-anchor" href="#the-usage-fee" aria-label="Permalink to &quot;The usage fee&quot;">​</a></h2><p>On each <strong>live winning close</strong>, 1% of the measured net profit buys and burns GNME in one Jupiter transaction. It is hardcoded (not a Settings knob), skipped on losses and mark-only closes, and logged-but-not-spent in paper mode. Details in the <a href="./faq#what-s-the-1-gnme-burn-fee">FAQ</a>.</p><h2 id="what-the-safety-net-cannot-do" tabindex="-1">What the safety net cannot do <a class="header-anchor" href="#what-the-safety-net-cannot-do" aria-label="Permalink to &quot;What the safety net cannot do&quot;">​</a></h2><p>Being honest about the limits:</p><ul><li>A <strong>well-executed slow rug</strong> passes vetting and bleeds out under the stop loss. Sizing caps are the only defense.</li><li>P0 fires on signals — TVL collapse, dumps, whale changes, metadata flips — but a rug that beats the 15s poll can still take most of a position.</li><li>RugCheck free reports are cached upstream; our own RPC checks are the fresh layer, and RugCheck is only ever a veto.</li><li>The stop loss (P1) realizes −25%+ by definition. The live book&#39;s P1 exits were dump-throughs that kept falling after exit — the stop is doing its job, not failing.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./strategy">Strategy reference</a> — the P0–P5 ladder these brakes protect</li><li><a href="./configuration">Configuration reference</a> — every brake threshold as a key</li><li><a href="./faq">FAQ</a> — &quot;Can I lose money?&quot; and other direct answers</li><li><a href="./how-it-works">How it works</a> — the pipeline overview</li><li><a href="./cli">CLI reference</a> — <code>halt</code>, <code>pause</code>, <code>status</code>, <code>force-close</code></li></ul>',39)])])}const u=t(r,[["render",n]]);export{p as __pageData,u as default};
